 export const loadYocoScript = () => {
  return new Promise((resolve, reject) => {
    // If it's already loaded, resolve immediately
    if (typeof window.Yoco !== 'undefined') {
      resolve(window.Yoco);
      return;
    }

    // Instead of creating a script tag, we fetch the raw code and eval it
    // This bypasses the "mixed content" blocking on localhost
    fetch('https://js.yoco.com/sdk/v1/yoco-sdk.js')
      .then(response => response.text())
      .then(code => {
        // Execute the code in the window context
        const func = new Function(code);
        func();
        
        // Wait a moment for the object to initialize, then resolve
        setTimeout(() => {
          if (typeof window.Yoco !== 'undefined') {
            resolve(window.Yoco);
          } else {
            reject(new Error('Yoco SDK loaded but not initialized'));
          }
        }, 300);
      })
      .catch((err) => {
        reject(new Error('Failed to load Yoco SDK: ' + err.message));
      });
  });
};
